#!/usr/bin/env bash
# Question 1: Ready, but one worker misbehaves. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q1_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q1_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q1_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
rm -rf /opt/course/degraded
mkdir -p /opt/course/degraded
chown -R ubuntu:ubuntu /opt/course
printf '%s\n' "${Q1_NODE}" > "/var/tmp/cka-q1.worker"
: > "/var/tmp/cka-q1.cause"
chmod 600 "/var/tmp/cka-q1.worker" "/var/tmp/cka-q1.cause"
for n in "worker-1" "worker-2"; do kubectl label node "$n" fleet=edge --overwrite >/dev/null; done
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: fleet-check
  namespace: ${Q1_NS}
spec:
  selector:
    matchLabels: { app: fleet-check }
  template:
    metadata:
      labels: { app: fleet-check }
    spec:
      nodeSelector: { fleet: edge }
      terminationGracePeriodSeconds: 1
      containers:
        - name: probe
          image: busybox:1.36
          command: ["sh", "-c", "mkdir -p /www; echo fleet-ok > /www/index.html; exec httpd -f -p 8080 -h /www"]
          readinessProbe:
            exec: { command: ["nslookup", "kubernetes.default.svc.cluster.local"] }
            periodSeconds: 5
            timeoutSeconds: 4
            failureThreshold: 2
          resources:
            requests: { cpu: 10m, memory: 8Mi }
EOF
kubectl -n "${Q1_NS}" rollout status daemonset/fleet-check --timeout=240s
kubectl -n "${Q1_NS}" get daemonset fleet-check -o jsonpath='{.metadata.uid} {.spec.template.spec}' > "/var/tmp/cka-q1.fleet"
chmod 644 "/var/tmp/cka-q1.fleet"

case "${Q1_FAULT}" in
  kubelet-port-blocked)
    printf '%s\n' firewall >> "/var/tmp/cka-q1.cause"
    ;;
  cluster-dns-wrong)
    printf '%s\n' kubelet >> "/var/tmp/cka-q1.cause"
    ;;
  sandbox-image-wrong)
    printf '%s\n' containerd >> "/var/tmp/cka-q1.cause"
    ;;
  cni-binary-missing)
    printf '%s\n' cni >> "/var/tmp/cka-q1.cause"
    ;;
  overlay-blocked)
    printf '%s\n' firewall >> "/var/tmp/cka-q1.cause"
    ;;
  disk-full)
    printf '%s\n' disk >> "/var/tmp/cka-q1.cause"
    ;;
  node-object-deleted)
    printf '%s\n' node-registration >> "/var/tmp/cka-q1.cause"
    kubectl delete node "${Q1_NODE}"
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
